import{_ as t,g as a,e as r,a4 as c}from"./chunks/framework.CEYJDsBW.js";const s=JSON.parse('{"title":"dev.anvilcraft.resource.ageratum","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/21.1/api/dev-anvilcraft-resource-ageratum.md","filePath":"ageratum/21.1/api/dev-anvilcraft-resource-ageratum.md"}'),d={name:"ageratum/21.1/api/dev-anvilcraft-resource-ageratum.md"};function o(i,e,n,u,b,l){return a(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="dev-anvilcraft-resource-ageratum" tabindex="-1">dev.anvilcraft.resource.ageratum <a class="header-anchor" href="#dev-anvilcraft-resource-ageratum" aria-label="Permalink to &quot;dev.anvilcraft.resource.ageratum&quot;">​</a></h1><h2 id="ageratum" tabindex="-1">Ageratum <a class="header-anchor" href="#ageratum" aria-label="Permalink to &quot;Ageratum&quot;">​</a></h2><p>相关用法 · <a href="../guides/open.html">从服务端打开页面</a></p><p><code>public class Ageratum</code></p><p><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L32" target="_blank" rel="noreferrer">类型声明</a></p><p>Ageratum 模组主类。 该模组定位为“游戏内手册框架”，用于为其它模组提供统一的文档展示能力。 当前负责模组初始化与文档打开入口。</p><p>类型注解 <code>@Mod(Ageratum.MOD_ID)</code></p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static final String MOD_ID</code></td><td>模组 ID，也是默认命名空间。<br>初值 <code>&quot;ageratum&quot;</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L37" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final DeferredRegister.Items ITEMS</code></td><td>初值 <code>DeferredRegister.createItems(Ageratum.MOD_ID)</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L38" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final DeferredRegister&lt;CreativeModeTab&gt; TABS</code></td><td>初值 <code>DeferredRegister.create(Registries.CREATIVE_MODE_TAB, Ageratum.MOD_ID)</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L39" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final DeferredItem&lt;Item&gt; DEFAULT_GUIDE_ITEM</code></td><td>初值 <code>ITEMS.register( &quot;guidebook&quot;, () -&gt; new Item(new Item.Properties().stacksTo(1)) )</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L40" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public static final DeferredHolder&lt;CreativeModeTab, CreativeModeTab&gt; DEFAULT_TAB</code></td><td>由 <code>TABS.register</code> 初始化。</td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L44" target="_blank" rel="noreferrer">字段</a></td></tr><tr><td><code>public Ageratum(IEventBus modEventBus, ModContainer modContainer)</code></td><td>模组构造函数，由 NeoForge 在加载时调用。<br>参数 <code>modEventBus</code> 模组专属事件总线<br>参数 <code>modContainer</code> 模组容器<br>实现调用 <code>ITEMS.register(modEventBus)</code><br>实现调用 <code>TABS.register(modEventBus)</code><br>实现调用 <code>NeoForge.EVENT_BUS.register(this)</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L62" target="_blank" rel="noreferrer">构造器</a></td></tr><tr><td><code>public static ResourceLocation location(String path)</code></td><td>生成以本模组 ID 为命名空间的 ResourceLocation。<br>参数 <code>path</code> 资源路径（不含命名空间前缀）<br>返回 完整的资源位置<br>末尾返回 <code>ResourceLocation.fromNamespaceAndPath(Ageratum.MOD_ID, path)</code><br><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/constants/AgeratumConstants.java#L197" target="_blank" rel="noreferrer">调用处 AgeratumConstants.GuideScreenUI.Textures</a></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L74" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static void openGuide(ServerPlayer player, ResourceLocation location)</code></td><td>打开指定资源位置的文档。 客户端调用：直接尝试打开文档界面。 服务端调用：通过网络包通知客户端打开文档。 若文档不存在则忽略，不抛出异常。<br>执行 <code>AgeratumNetwork.sendOpenGuide(player, location)</code><br><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L94" target="_blank" rel="noreferrer">调用处 Ageratum.useGuideItem</a></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L85" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@SubscribeEvent public void useGuideItem(PlayerInteractEvent.RightClickItem event)</code></td><td>事件总线派发 <code>PlayerInteractEvent.RightClickItem</code> 时调用。<br>实现调用 <code>event.getEntity()</code><br>实现调用 <code>event.getItemStack()</code><br>实现调用 <code>stack.is(Ageratum.DEFAULT_GUIDE_ITEM.get())</code></td><td><a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/Ageratum.java#L89" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table>',8)])])}const g=t(d,[["render",o]]);export{s as __pageData,g as default};
